from collections import deque
H,W=14,14
seen=[[False]*W for _ in range(H)]
q=deque()
for r in range(H):
    for c in [0,W-1]:
        if g[r][c]==6 and not seen[r][c]: seen[r][c]=True;q.append((r,c))
for c in range(W):
    for r in [0,H-1]:
        if g[r][c]==6 and not seen[r][c]: seen[r][c]=True;q.append((r,c))
while q:
    r,c=q.popleft()
    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
        nr,nc=r+dr,c+dc
        if 0<=nr<H and 0<=nc<W and g[nr][nc]==6 and not seen[nr][nc]:
            seen[nr][nc]=True;q.append((nr,nc))
out=[row[:] for row in g]
fill=[(r,c) for r in range(H) for c in range(W) if g[r][c]==6 and not seen[r][c]]
print(fill)
for r,c in fill: out[r][c]=4
for row in out: print(' '.join(map(str,row)))
import json; print(json.dumps({"action":"submit","grid":out}))
